const $=(q,root=document)=>root.querySelector(q),$$=(q,root=document)=>[...root.querySelectorAll(q)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<span class="icon" aria-hidden="true">${name}</span>`;
const button=(label,action,kind='secondary',glyph='')=>`<button type="button" class="es-btn es-btn--sm es-btn--${kind}" data-action="${action}">${glyph?icon(glyph):''}${label}</button>`;
const ib=(glyph,action,title)=>`<button type="button" class="icon-btn" data-action="${action}" title="${esc(title)}" aria-label="${esc(title)}">${icon(glyph)}</button>`;
const field=(label,name,value='',type='text',hint='',attrs='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}>${hint?`<small>${hint}</small>`:''}</label>`;
const date=v=>v?new Date(v).toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit',year:'numeric'}):'—';
const datetime=v=>v?new Date(v).toLocaleString('de-DE',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):'—';
const num=v=>Number(v||0).toLocaleString('de-DE');
const bytes=v=>v>=1048576?(v/1048576).toLocaleString('de-DE',{maximumFractionDigits:1})+' MB':v>=1024?Math.ceil(v/1024)+' KB':v+' B';
const initials=name=>name.split(' ').map(v=>v[0]).slice(0,2).join('').toUpperCase();
const FEATURES={files:['Dateien & Projekte','Eigene Dateien und Projekte verwalten.'],editor:['Code-Editor','Dateien bearbeiten, speichern und testen.'],html:['Web & JavaScript','HTML, CSS und JavaScript in der Vorschau ausführen.'],php:['PHP','PHP in der isolierten Browser-Laufzeit ausführen.'],python:['Python','Python-Scripts in der isolierten Browser-Laufzeit testen.'],database:['MySQL-Datenbanken','Eigene Datenbanken verbinden und verwalten.'],chat:['Gruppenchat','Mit Mitgliedern der eigenen Gruppen austauschen.']};
