let user,csrf,flags={},routeVersion=0,runVersion=0,openVersion=0,editor=null,activeFile=null,activeProject=null,dirty=false,chatTimer=null,runJob=null,files=[],projects=[],dbInfo=null,selectedTable=null,dbOffset=0,chatGroup=null;
const admin=location.pathname.startsWith('/admin');
const app=$('#app');
function toast(message,error=false){const item=document.createElement('div');item.className='toast'+(error?' error-toast':'');item.textContent=message;$('#notifications').append(item);setTimeout(()=>item.remove(),error?7000:3500);}
async function api(action,data=null){
  const read=data===null;const url='/api/?'+new URLSearchParams({action,...(read?{}:{})});
  const response=await fetch(url,{method:read?'GET':'POST',headers:read?{}:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:read?undefined:JSON.stringify(data),credentials:'same-origin'});
  let result;try{result=await response.json();}catch{throw Error('Der Server hat keine gültige Antwort geliefert.');}
  if(!response.ok){if(response.status===401 && action!=='login'){user=null;await boot();}throw Object.assign(Error(result.error||'Die Anfrage ist fehlgeschlagen.'),{status:response.status});}
  return result;
}
async function get(action,params={}) {
  const response=await fetch('/api/?'+new URLSearchParams({action,...params}),{credentials:'same-origin'});let data;
  try{data=await response.json();}catch{throw Error('Der Server hat keine gültige Antwort geliefert.');}
  if(!response.ok){if(response.status===401){user=null;await boot();}throw Error(data.error||'Die Anfrage ist fehlgeschlagen.');}return data;
}
function bind(action,fn,root=document){$$(`[data-action="${action}"]`,root).forEach(el=>el.onclick=async e=>{try{await fn(e,el);}catch(error){toast(error.message,true);}});}
function empty(title,copy,glyph='folder_open',cta=''){return `<div class="empty">${icon(glyph)}<h3>${title}</h3><p>${copy}</p>${cta}</div>`;}
function pageHead(index,title,copy,cta=''){return `<div class="page-head"><div><div class="meta">${index} // ${admin?'ADMINISTRATION':'MEIN WORKSPACE'}</div><h1>${title}</h1><p>${copy}</p></div>${cta}</div>`;}
function modal(title,body,onSubmit,label='Speichern',options={}) {
  const dialog=$('#modal');dialog.setAttribute('aria-labelledby','modal-title');dialog.innerHTML=`<form id="modal-form"><div class="dialog-head"><h2 id="modal-title">${title}</h2>${ib('close','close-modal','Schließen')}</div><div class="dialog-body">${body}<div class="error" role="alert"></div></div><div class="dialog-foot">${button('Abbrechen','close-modal')}${button(label,'submit-modal','primary')}</div></form>`;
  let closed;const result=new Promise(r=>closed=r);const close=()=>{dialog.close();closed(false);};bind('close-modal',close,dialog);dialog.oncancel=()=>closed(false);
  const form=$('#modal-form');const submit=$('[data-action="submit-modal"]',form);submit.type='submit';
  form.onsubmit=async e=>{e.preventDefault();submit.disabled=true;$('.error',form).textContent='';try{await onSubmit(new FormData(form),form);dialog.close();closed(true);}catch(err){$('.error',form).textContent=err.message;}finally{submit.disabled=false;}};
  dialog.showModal();options.after?.(dialog);return result;
}
async function confirm(title,copy,label='Löschen'){return modal(title,`<p>${esc(copy)}</p>`,async()=>{},label);}
async function leaveDirty(){return !dirty||await confirm('Ungespeicherte Änderungen','Ihre letzten Änderungen sind noch nicht gespeichert. Möchten Sie die Datei trotzdem verlassen?','Verlassen');}
function resetWorkspace(){++runVersion;++openVersion;editor?.destroy();editor=null;activeFile=null;dirty=false;runJob?.stop();runJob=null;clearInterval(chatTimer);chatTimer=null;}
async function boot(){
  try{const data=await api('bootstrap');user=data.user;csrf=data.csrf;flags=data.features;
    if(!user){login(data.setup_required);return;}
    if((user.role==='admin')!==admin){location.href=user.role==='admin'?'/admin/':'/';return;}
    shell();if(user.must_change_password)await passwordModal(true);await route();
  }catch(e){app.innerHTML=empty('Die Anwendung ist noch nicht bereit',esc(e.message),'settings');}
}
function login(setupRequired){
  const setup=setupRequired&&admin;
  app.innerHTML=`<div class="login"><section class="login-story"><img src="/assets/brand/logo-dark.svg" alt="Entrosphere"><div><div class="meta">DEVELOPER // ${admin?'ADMINISTRATION':'LEARNING WORKSPACE'}</div><h1>Verstehen.<br>Entwickeln.<br><span>Weiterdenken.</span></h1><p>Ein eigener Raum für Ideen, Code und den nächsten Schritt.</p><div class="login-indices"><div><small>01 // CODE</small><strong>Ausprobieren.</strong></div><div><small>02 // RUN</small><strong>Ergebnisse sehen.</strong></div><div><small>03 // LEARN</small><strong>Gemeinsam lernen.</strong></div></div></div><footer class="meta">ENTROSPHERE DEVELOPER<br>HTML · CSS · JAVASCRIPT · PHP · PYTHON</footer></section><section class="login-panel"><div class="login-form"><div class="meta"><span class="accent">${admin?'02':'01'}</span> // ${setup?'ERSTE EINRICHTUNG':admin?'ADMIN-ZUGANG':'IHR ZUGANG'}</div><h2>${setup?'Bereit für den Start.':admin?'Alles im Blick.':'Willkommen zurück.'}</h2><p>${setup?'Erstellen Sie den ersten Administrator mit Ihrem Einrichtungsschlüssel.':admin?'Benutzer, Gruppen und Freigaben an einem Ort.':'Melden Sie sich an und machen Sie dort weiter, wo Ihre letzte Idee aufgehört hat.'}</p><form class="form" id="login-form">${setup?field('Einrichtungsschlüssel','token','','password','Aus dem GitHub-Secret APP_SETUP_TOKEN.','required autocomplete="off"')+field('Ihr Name','name','','text','','required autocomplete="name"'):''}${field('E-Mail-Adresse','email','','email','','required autocomplete="username"')}${field('Passwort','password','','password',setup?'Mindestens 12 Zeichen.':'','required autocomplete="'+(setup?'new-password':'current-password')+'"')}<div class="error" role="alert"></div><button class="es-btn es-btn--primary" type="submit">${setup?'Administrator erstellen':'Anmelden'}${icon('arrow_forward')}</button></form><div class="form-foot"><span class="muted">${admin?'Lernumgebung':'Zugang erhalten Sie von Ihrer Kursleitung.'}</span><a href="${admin?'/':'/admin/'}">${admin?'Zum Benutzer-Login':'Admin-Zugang'} ${icon('arrow_forward')}</a></div></div></section></div>`;
  $('#login-form').onsubmit=async e=>{e.preventDefault();const form=e.target,submit=$('button[type="submit"]',form),data=Object.fromEntries(new FormData(form));submit.disabled=true;$('.error',form).textContent='';try{if(setup){await api('setup',data);toast('Ihr Administrator wurde angelegt.');login(false);}else{const result=await api('login',{...data,portal:admin?'admin':'user'});user=result.user;csrf=result.csrf;flags=result.features;shell();if(user.must_change_password)await passwordModal(true);await route();}}catch(err){$('.error',form).textContent=err.message;}finally{submit.disabled=false;}};
}
function shell(){
  const nav=admin?[['dashboard','Übersicht','space_dashboard'],['users','Benutzer','person'],['groups','Gruppen','groups'],['features','Freigaben','tune'],['statistics','Nutzungsstatistik','query_stats']]:[['dashboard','Übersicht','space_dashboard'],...(flags.files?[['files','Dateien','folder_open']]:[]),...(flags.editor?[['editor','Entwicklungsumgebung','code']]:[]),...(flags.database?[['database','Datenbanken','database']]:[]),...(flags.chat?[['chat','Gruppenchat','forum']]:[])];
  app.innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><a class="brand" href="#dashboard"><img src="/assets/brand/logo.svg" alt="Entrosphere"></a><div class="product-label">DEVELOPER ${admin?'// ADMIN':''}</div><div class="nav-label">${admin?'VERWALTUNG':'LERNUMGEBUNG'}</div><nav class="nav" aria-label="Hauptnavigation">${nav.map(([r,label,glyph],i)=>`<a href="#${r}" data-route="${r}">${icon(glyph)}${label}<span class="nav-index">0${i+1}</span></a>`).join('')}</nav><div class="sidebar-bottom"><div class="workspace-note"><div class="meta">${admin?'SYSTEM & ZUGÄNGE':'RAUM FÜR FORTSCHRITT'}</div><p>${admin?'Klare Freigaben. Eigene Arbeitsbereiche.':user.groups.length?esc(user.groups.map(g=>g.name).join(' · ')):'Ihr persönlicher Workspace.'}</p></div><div class="account"><button class="avatar" data-action="password" title="Passwort ändern" aria-label="Passwort ändern">${esc(initials(user.name))}</button><div><div class="name">${esc(user.name)}</div><small>${admin?'Administrator':'Lernender'}</small></div>${ib('logout','logout','Abmelden')}</div></div></aside><main class="main"><header class="topbar"><div style="display:flex;align-items:center;gap:12px">${ib('menu','menu','Navigation öffnen').replace('icon-btn','icon-btn menu-toggle')}<div class="meta">${admin?'ADMINISTRATION':'LEARNING WORKSPACE'} <span class="accent">/</span> <span id="breadcrumb">Übersicht</span></div></div><div class="topbar-right"><span class="status">Workspace bereit</span><span class="meta">${new Date().toLocaleDateString('de-DE',{day:'2-digit',month:'long',year:'numeric'})}</span></div></header><div id="view"></div></main></div>`;
  bind('logout',async()=>{if(!await leaveDirty())return;resetWorkspace();await api('logout',{});user=null;location.hash='';await boot();});
  $('#sidebar .product-label').insertAdjacentHTML('afterend',ib('close','menu-close','Navigation schließen').replace('icon-btn','icon-btn sidebar-close'));
  bind('password',()=>passwordModal(false));bind('menu',()=>$('#sidebar').classList.toggle('open'));bind('menu-close',()=>$('#sidebar').classList.remove('open'));
}
async function passwordModal(required){
  let done=false;while(!done){done=await modal(required?'Neues Passwort festlegen':'Passwort ändern',`<p>${required?'Bitte ersetzen Sie Ihr vorläufiges Passwort, bevor Sie Ihren Workspace öffnen.':'Verwenden Sie ein langes Passwort, das Sie nur hier nutzen.'}</p>${field('Bisheriges Passwort','current','','password','','required autocomplete="current-password"')}${field('Neues Passwort','password','','password','Mindestens 12 Zeichen.','required minlength="12" autocomplete="new-password"')}${field('Neues Passwort wiederholen','repeat','','password','','required autocomplete="new-password"')}`,async data=>{if(data.get('password')!==data.get('repeat'))throw Error('Die neuen Passwörter stimmen nicht überein.');await api('password',Object.fromEntries(data));user.must_change_password=false;toast('Ihr Passwort wurde geändert.');},'Passwort speichern');if(!required)break;}
}
let lastHash=location.hash||'#dashboard';
addEventListener('hashchange',async()=>{
  if(!user)return;if(!await leaveDirty()){history.replaceState(null,'',lastHash);return;}lastHash=location.hash;try{await route();}catch(e){toast(e.message,true);}
});
addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
addEventListener('keydown',e=>{if(e.key==='Escape')$('#sidebar')?.classList.remove('open');});
async function route(){
  resetWorkspace();const version=++routeVersion;const name=location.hash.slice(1)||'dashboard';$('#sidebar')?.classList.remove('open');
  $$('.nav a').forEach(a=>a.setAttribute('aria-current',a.dataset.route===name?'page':'false'));const label=$(`.nav a[data-route="${name}"]`);$('#breadcrumb').textContent=label?label.childNodes[1].textContent:'Übersicht';
  $('#view').innerHTML='<div class="loading-page">Workspace wird geladen …</div>';
  const allowed=admin?{dashboard:adminOverview,users:adminUsers,groups:adminGroups,features:adminFeatures,statistics:adminStatistics}:{dashboard,files:flags.files&&fileManager,editor:flags.editor&&programming,database:flags.database&&database,chat:flags.chat&&chat};
  const fn=allowed[name]||allowed.dashboard;try{await fn(version);}catch(e){if(version===routeVersion)$('#view').innerHTML=`<div class="content">${empty('Dieser Bereich ist gerade nicht verfügbar',esc(e.message),'info',button('Erneut versuchen','retry'))}</div>`;bind('retry',()=>route());}
}
function render(html,version){if(version!==routeVersion)return false;$('#view').innerHTML=html;return true;}
function stats(items){return `<div class="stats-grid">${items.map(([label,value,copy])=>`<div class="stat"><div class="meta">${label}</div><strong>${value}</strong><small>${copy}</small></div>`).join('')}</div>`;}
function projectDialog(onCreated){
  const available=[['web','html','Web-Projekt','HTML, CSS und JavaScript.'],['php','php','PHP-Website','Dynamische Seiten mit PHP.'],['python','python','Python-Script','Ideen mit Python ausprobieren.']].filter(x=>flags[x[1]]);
  if(!available.length){toast('Es ist keine Projektsprache freigegeben.',true);return;}
  return modal('Neues Projekt',`${field('Projektname','name','','text','','required maxlength="80" placeholder="Zum Beispiel: Meine erste Website"')}<div class="field" style="margin-top:24px"><span>Startpunkt</span><div class="template-options">${available.map(([value,,label,copy],i)=>`<label><input type="radio" name="template" value="${value}" ${i===0?'checked':''}><div><strong>${label}</strong><small>${copy}</small></div></label>`).join('')}</div></div>`,async data=>{const result=await api('project.create',Object.fromEntries(data));activeProject=result.id;sessionStorage.setItem('project',result.id);toast('Ihr Projekt ist bereit.');onCreated?.(result.id);},'Projekt erstellen');
}
async function dashboard(version){
  const d=await api('dashboard');projects=d.projects;
  const greeting=new Date().getHours()<12?'Guten Morgen':new Date().getHours()<18?'Guten Tag':'Guten Abend';
  const html=`<div class="content">${pageHead('01',`${greeting},<br>${esc(user.name)}<span class="accent">.</span>`,'Ihr nächster Schritt beginnt hier.',flags.files?button('Neues Projekt','new-project','primary','add'):'')}${stats([['PROJEKTE',num(d.projects.length),'Eigene Ideen in Entwicklung'],['DATEIEN',num(d.stats.files),'In Ihrem persönlichen Space'],['AUSFÜHRUNGEN',num(d.runs),'Code ausprobiert und getestet'],['SPEICHER',bytes(d.stats.bytes),'Von 20 MB verfügbar']])}<section class="hero"><div class="hero-copy"><div class="meta">01 // AUS IDEEN WIRD CODE</div><h2>Ihr Raum.<br>Ihre nächste <span>Idee.</span></h2><p>Schreiben, testen, verstehen. Alles, was Sie für Ihren nächsten Entwicklungsschritt brauchen.</p>${flags.editor?button(d.projects.length?'Weiterentwickeln':'Projekt starten','continue','primary','arrow_forward'):''}</div><div class="hero-code"><div class="meta">WORKSPACE / INDEX.HTML</div><div class="code-sample"><span class="dim">01</span>  <span class="pink">&lt;main&gt;</span>\n<span class="dim">02</span>    <span class="pink">&lt;h1&gt;</span><span class="white">Hallo, Welt.</span><span class="pink">&lt;/h1&gt;</span>\n<span class="dim">03</span>    <span class="pink">&lt;p&gt;</span>Hier beginnt etwas.<span class="pink">&lt;/p&gt;</span>\n<span class="dim">04</span>  <span class="pink">&lt;/main&gt;</span>\n\n<span class="dim">// Die beste Art zu lernen: machen.</span></div></div></section><div class="section-head"><h2>Ihre Projekte</h2><span class="meta">${num(d.projects.length)} // WORK IN PROGRESS</span></div>${d.projects.length?`<div class="project-grid">${d.projects.map((p,i)=>`<button class="project-card" data-project="${p.id}"><div class="meta"><span class="accent">${String(i+1).padStart(2,'0')}</span> // PROJEKT</div><h3>${esc(p.name)}</h3><div class="card-foot"><span>${num(p.file_count)} Dateien · ${date(p.updated_at)}</span>${icon('arrow_forward')}</div></button>`).join('')}</div>`:empty('Platz für Ihre erste Idee','Starten Sie mit einer Web-Seite, einem PHP-Projekt oder einem Python-Script.','code',flags.files?button('Projekt erstellen','new-project','primary'):'')}<div class="section-head"><h2>Zuletzt passiert</h2><span class="meta">IHRE AKTIVITÄT</span></div><div class="activity-list">${d.activity.map(e=>`<div class="activity-item"><span>${EVENTS[e.event]||'Workspace-Aktivität'}</span><time>${datetime(e.created_at)}</time></div>`).join('')||'<div class="activity-item muted">Hier erscheinen Ihre nächsten Schritte.</div>'}</div></div>`;
  if(!render(html,version))return;
  bind('new-project',()=>projectDialog(()=>{location.hash='editor';if(location.hash==='#editor')route();}));
  bind('continue',()=>{if(d.projects.length){sessionStorage.setItem('project',d.projects[0].id);location.hash='editor';}else return projectDialog(()=>location.hash='editor');});
  $$('[data-project]').forEach(el=>el.onclick=()=>{sessionStorage.setItem('project',el.dataset.project);location.hash=flags.editor?'editor':'files';});
}
async function loadProjects(){projects=(await api('projects')).projects;const stored=sessionStorage.getItem('project');activeProject=projects.find(p=>p.id===stored)?.id||projects[0]?.id;return projects;}
function projectSelect(){return `<label class="field"><span class="hidden">Projekt auswählen</span><select id="project-select">${projects.map(p=>`<option value="${p.id}" ${p.id===activeProject?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`;}
async function fileManager(version){
  await loadProjects();if(!activeProject){render(`<div class="content">${pageHead('02','Ihre Dateien<span class="accent">.</span>','Ein klarer Platz für jedes Projekt.',button('Neues Projekt','new-project','primary','add'))}${empty('Ihr Space ist bereit','Legen Sie Ihr erstes Projekt an, um Dateien zu erstellen.','folder_open')}</div>`,version);bind('new-project',()=>projectDialog(()=>route()));return;}
  const data=await get('files',{project:activeProject});files=data.files;
  if(!render(`<div class="content">${pageHead('02','Ihre Dateien<span class="accent">.</span>','Erstellen, bearbeiten und direkt im Browser ausprobieren.',button('Neue Datei','new-file','primary','add'))}<div class="toolbar">${projectSelect()}${button('Projekt','new-project','secondary','add')}${button('Ordner','new-folder','secondary','create_new_folder')}<span class="spacer"></span>${ib('edit','rename-project','Projekt umbenennen')}${ib('delete','delete-project','Projekt löschen')}</div>${files.length?`<div class="table-wrap"><table><thead><tr><th>Datei / Pfad</th><th>Typ</th><th>Größe</th><th>Geändert</th><th><span class="hidden">Aktionen</span></th></tr></thead><tbody>${files.map(f=>`<tr data-file="${esc(f.path)}"><td><button class="link file-name" data-action="open-file">${icon(f.kind==='directory'?'folder':'draft')}${esc(f.path)}</button></td><td><span class="tag">${esc(f.kind==='directory'?'Ordner':f.path.split('.').pop().toUpperCase())}</span></td><td class="muted">${f.kind==='directory'?'—':bytes(f.bytes)}</td><td class="muted">${date(f.updated_at)}</td><td><div class="actions">${/\.(html?|php)$/.test(f.path)?ib('open_in_new','preview-file','Im Browser öffnen'):''}${f.kind==='file'?ib('download','download-file','Datei herunterladen'):''}${ib('edit','rename-file','Umbenennen')}${ib('delete','delete-file','Löschen')}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Dieses Projekt ist noch leer','Erstellen Sie eine Datei, um loszulegen.','draft') }<div class="notice">HTML- und PHP-Dateien öffnen Sie über ${icon('open_in_new')} in einer eigenen Browser-Vorschau. Ihr Code bleibt in Ihrem persönlichen Workspace.</div></div>`,version))return;
  $('#project-select').onchange=e=>{sessionStorage.setItem('project',e.target.value);route();};
  bind('new-project',()=>projectDialog(()=>route()));bind('new-file',()=>fileDialog(false,()=>route()));bind('new-folder',()=>fileDialog(true,()=>route()));
  bind('open-file',async(e,el)=>{const path=el.closest('tr').dataset.file;if(files.find(f=>f.path===path)?.kind==='directory')return;sessionStorage.setItem('file',path);location.hash='editor';});
  bind('preview-file',(e,el)=>openPreview(el.closest('tr').dataset.file));
  bind('download-file',async(e,el)=>{const path=el.closest('tr').dataset.file;const {file}=await get('file',{project:activeProject,path});download(new Blob([file.content],{type:'text/plain;charset=utf-8'}),path.split('/').pop());});
  bind('rename-file',(e,el)=>renameFile(el.closest('tr').dataset.file));
  bind('delete-file',async(e,el)=>{const path=el.closest('tr').dataset.file;if(await confirm('Datei löschen',`„${path}“ und enthaltene Dateien werden dauerhaft gelöscht.`)){await api('file.delete',{project:activeProject,path});await route();}});
  bind('rename-project',()=>modal('Projekt umbenennen',field('Projektname','name',data.project.name,'text','','required maxlength="80"'),async fd=>{await api('project.rename',{id:activeProject,name:fd.get('name')});await route();}));
  bind('delete-project',async()=>{if(await confirm('Projekt löschen',`„${data.project.name}“ und alle Dateien werden dauerhaft gelöscht.`)){await api('project.delete',{id:activeProject});sessionStorage.removeItem('project');await route();}});
}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openPreview(path){window.open('/preview.php?'+new URLSearchParams({project:activeProject,path}),'_blank','noopener,noreferrer');}
