async function loadTables(){const data=await api('db.tables');const select=$('#table-select');if(!select)return;select.innerHTML='<option value="">Tabelle auswählen</option>'+data.tables.map(t=>`<option ${selectedTable===t?'selected':''}>${esc(t)}</option>`).join('');}
