  if(!groups.length){render(`<div class="content">${pageHead('05','Gemeinsam weiterdenken<span class="accent">.</span>','Fragen stellen, Ideen teilen und voneinander lernen.')}${empty('Noch keiner Gruppe zugeordnet','Ihre Kursleitung kann Sie einer Gruppe zuordnen. Danach finden Sie hier den gemeinsamen Chat.','groups')}</div>`,version);return;}
