  let after=0,polling=false;
  const poll=async()=>{if(polling||document.hidden)return;polling=true;const gid=chatGroup;try{const data=await get('chat',{group:gid,after});if(gid!==chatGroup||!$('#messages'))return;const messages=$('#messages'),nearBottom=messages.scrollHeight-messages.scrollTop-messages.clientHeight<80;for(const m of data.messages){if(m.id<=after)continue;const item=document.createElement('article');item.className='message';item.innerHTML=`<div class="message-head"><strong class="${m.user_id===user.id?'me':''}">${esc(m.name)}</strong><time>${datetime(m.created_at)}</time></div><p>${esc(m.body)}</p>`;messages.append(item);after=m.id;}if(nearBottom)messages.scrollTop=messages.scrollHeight;}catch(e){clearInterval(chatTimer);toast(e.message,true);}finally{polling=false;}};
  const select=async gid=>{chatGroup=gid;after=0;$('#messages').replaceChildren();$('#chat-title').textContent=groups.find(g=>g.id===gid).name;$$('[data-group]').forEach(el=>el.classList.toggle('active',el.dataset.group===gid));await poll();};
  $$('[data-group]').forEach(el=>el.onclick=()=>select(el.dataset.group));await select(chatGroup);chatTimer=setInterval(poll,4000);
